testcase.name:
test_query_with_fragments_have_same_multiplied_complexity_cost[
query productsQueryCost($channel: String, $first: Int) {
 products(channel: $channel, first: $first) {
 edges {
 node {
 id
 category {
 ... on Category {
 products(channel: $channel, first: $first) {
 edges {
 node {
 id
 }
 }
 }
 }
 }
 }
 }
 }
}
]

test_query_with_fragments_have_same_multiplied_complexity_cost[
fragment category on Category {
 products(channel: $channel, first: $first) {
 edges {
 node {
 id
 }
 }
 }
}

query productsQueryCost($channel: String, $first: Int) {
 products(channel: $channel, first: $first) {
 edges {
 node {
 id
 category {
 ...category
 }
 }
 }
 }
}
]

test_query_with_fragments_have_same_multiplied_complexity_cost[
query productsQueryCost($channel: String, $first: Int) {
 products(channel: $channel, first: $first) {
 edges {
 node {
 id
 category{
 products(channel: $channel, first: $first) {
 edges{
 node{
 id
 }
 }
 }
 }
 }
 }
 }
}
]
